        const BindingFlags InstanceMembers = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
        const BindingFlags StaticMembers = BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

        public static dynamic? getattr(object? o, string name) =>
            TryGetAttr(o, name, out var v) ? v : throw new MissingMemberException($"'{(o == null ? "NoneType" : o is Type ? "type" : PyTypeName(o.GetType()))}' object has no attribute '{name}'");
        public static dynamic? getattr(object? o, string name, object? @default) => TryGetAttr(o, name, out var v) ? v : @default;
        public static bool hasattr(object? o, string name) => TryGetAttr(o, name, out _);

        public static dynamic __unbound_import(string name) => throw new NameError($"name '{name}' is not defined", name: name);

        /// <summary>
        /// An attribute by name: a property or field (of a class: a class variable), a method as a bound method, an
        /// attribute set on the object at run time, one of str's/list's/... Python methods, or a dynamic object's member.
        /// </summary>
        static bool TryGetAttr(object? o, string name, out object? value, bool allowFallback = true)
        {
            value = null;
            if (o == null && name == "__class__") { value = __type_of(o); return true; }
            if (o == null || name.StartsWith("<")) return false;
            if (o is Typhon.Stdlib.builtins.super proxy && proxy.TryResolve(name, out value)) return true;
            if (o is PyModule module)
            {
                if (name == "__dict__") { value = module.__dict__; return true; }
                if (name == "__class__") { value = typeof(PyModule); return true; }
                return module.__dict__.TryGetValue(name, out value);
            }
            if (o is Exception error && name == "__traceback__")
            {
                value = Typhon.Stdlib.types.TracebackType.Of(error);
                return true;
            }
            if (o is Type t)
            {
                if (name == "__name__" || name == "__qualname__") { value = PyTypeName(t); return true; }
                if (name == "__dict__") { value = PyClassDescriptors.Dictionary(t); return true; }
                if (name == "__module__") { value = __module_of(t); return true; }
                if (name == "__doc__") { value = t.GetCustomAttribute<PySourceAttribute>()?.DocString; return true; }
                if (PyClassDescriptors.TryGetAttribute(t, name, out value)) return true;
                if (name == "__module__") { value = ModuleOfType(t); return true; }
                if (TryGetClassData(t, name, out value)) return true;
                if (t.GetMethods(StaticMembers | InstanceMembers).Any(m => m.Name == name)) { value = new PyBoundMethod(t, name); return true; }
                if (FindNestedType(t, name) is Type nested) { value = nested; return true; }
                if (TryBuiltinClassMethod(t, name, out value)) return true;
                // CLR reflection consumers may also read members of the Type object itself.
            }
            if (o is PyFunction pf)
            {
                switch (name)
                {
                    case "__name__": value = pf.__name__; return true;
                    case "__qualname__": value = pf.__qualname__; return true;
                    case "__doc__": value = pf.__doc__; return true;
                    case "__wrapped__": if (pf.__wrapped__ == null) return false; value = pf.__wrapped__; return true;
                    case "__module__": value = pf.__module__; return true;
                }
                if (pf._attrs != null && pf._attrs.TryGetValue(name, out value)) return true;
            }
            if (o is System.Collections.IDictionary mapping && name is ("__getitem__" or "__contains__"))
            {
                value = new PyClosure(name, (args, keywords) =>
                {
                    if (args.Length != 1 || keywords?.Count > 0)
                        throw PyClosure.ArgCountError(name, 1, 1, args.Length);
                    return name == "__getitem__" ? (object?)__getitem(mapping, args[0]) : mapping.Contains(KeyFor(mapping, args[0]));
                });
                return true;
            }
            var type = o.GetType();
            if (type.GetProperty(name, InstanceMembers) is PropertyInfo p && p.GetIndexParameters().Length == 0)
            {
                bool lateAttribute = p.IsDefined(typeof(PyLateAttributeAttribute), false);
                if (lateAttribute && !allowFallback) return PyAttrDict.TryGetExtra(o, name, out value);
                try { value = Unwrapped(() => p.GetValue(o)); return true; }
                catch (MissingMemberException) when (lateAttribute) { return false; }
            }
            if (type.GetField(name, InstanceMembers) is FieldInfo f) { value = f.GetValue(o); return true; }
            if (PyAttrDict.TryGetExtra(o, name, out value)) return true;
            if (type.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                .Any(m => m.Name == name && (m.IsPublic || m.IsDefined(typeof(PySourceAttribute), false))))
            {
                value = new PyBoundMethod(o, name, includeNonPublic: true);
                return true;
            }
            if (PyClassDescriptors.TryGetAttribute(type, name, out value, instance: true)) return true;
            if (o is System.Collections.IDictionary dictionary && name == "get")
            {
                value = new PyClosure(name, (args, keywords) =>
                {
                    if (args.Length is < 1 or > 2 || keywords?.Count > 0)
                        throw PyClosure.ArgCountError(name, 1, 2, args.Length);
                    object? key = KeyFor(dictionary, args[0]);
                    return dictionary.Contains(key!) ? dictionary[key!] : args.Length == 2 ? args[1] : null;
                });
                return true;
            }
            switch (name)
            {
                case "__class__": value = __type_of(o); return true;
                case "__dict__": value = new PyAttrDict(o); return true;
            }
            // Python's methods of built-in values ("abc".upper, xs.count): Builtins' extension methods for this value
            var candidates = typeof(Builtins).GetMethods(BindingFlags.Static | BindingFlags.Public)
                .Where(m => m.Name == name && m.IsDefined(typeof(System.Runtime.CompilerServices.ExtensionAttribute), false))
                .Select(m => CloseFor(m, o.GetType())).Where(m => m != null && m.GetParameters()[0].ParameterType.IsInstanceOfType(o)).ToList();
            if (candidates.Count > 0)
            {
                var self = o;
                value = new PyClosure(name, (a, kw) => InvokeExtension(name, candidates!, self, a));
                return true;
            }
            if (o is System.Dynamic.IDynamicMetaObjectProvider)
            {
                try
                {
                    var site = System.Runtime.CompilerServices.CallSite<Func<System.Runtime.CompilerServices.CallSite, object, object>>.Create(
                        Microsoft.CSharp.RuntimeBinder.Binder.GetMember(Microsoft.CSharp.RuntimeBinder.CSharpBinderFlags.None, name, typeof(Builtins),
                            new[] { Microsoft.CSharp.RuntimeBinder.CSharpArgumentInfo.Create(Microsoft.CSharp.RuntimeBinder.CSharpArgumentInfoFlags.None, null) }));
                    value = site.Target(site, o);
                    return true;
                }
                catch (Microsoft.CSharp.RuntimeBinder.RuntimeBinderException) { }
                catch (MissingMemberException) { }
            }
            if (TryGetClassData(type, name, out value)) return true;
            if (FindNestedType(type, name) is Type nestedType) { value = nestedType; return true; }
            return allowFallback && TryFallbackAttribute(o, name, out value);
        }

        static bool TryGetClassData(Type type, string name, out object? value)
        {
            const BindingFlags DeclaredStatic = StaticMembers | BindingFlags.DeclaredOnly;
            for (Type? owner = type; owner != null; owner = owner.BaseType)
            {
                if (owner.GetProperty(name, DeclaredStatic) is PropertyInfo property && property.GetIndexParameters().Length == 0)
                { value = property.GetValue(null); return true; }
                if (owner.GetField(name, DeclaredStatic) is FieldInfo field)
                { value = field.GetValue(null); return true; }
            }
            value = null;
            return false;
        }

        static readonly ConditionalWeakTable<Type, ConcurrentDictionary<string, PyClosure>> BuiltinClassMethods = new();
        static readonly ILookup<string, MethodInfo> BuiltinExtensions = typeof(Builtins)
            .GetMethods(BindingFlags.Public | BindingFlags.Static)
            .Where(method => method.IsDefined(typeof(ExtensionAttribute), false)).ToLookup(method => method.Name);

        static bool TryBuiltinClassMethod(Type type, string name, out object? value)
        {
            bool applies = BuiltinExtensions[name].Any(method =>
            {
                Type receiver = method.GetParameters()[0].ParameterType;
                if (receiver.IsGenericParameter || receiver.IsByRef) return false;
                if (receiver.IsGenericType && receiver.ContainsGenericParameters) receiver = receiver.GetGenericTypeDefinition();
                return IsSubclass(type, receiver);
            });
            if (!applies) { value = null; return false; }
            var methods = BuiltinClassMethods.GetValue(type, _ => new ConcurrentDictionary<string, PyClosure>());
            value = methods.GetOrAdd(name, method =>
            {
                var implementation = new PyBoundMethod(typeof(Builtins), method);
                return new PyClosure(method, (args, keywords) =>
                {
                    if (args.Length == 0 || args[0] == null || !IsSubclass(args[0]!.GetType(), type))
                        throw new InvalidCastException($"descriptor '{method}' requires a '{PyTypeName(type)}' object");
                    return __invoke_kw(implementation, args, keywords);
                });
            });
            return true;
        }

        static readonly System.Collections.Concurrent.ConcurrentDictionary<string, PyBoundMethod> ObjectMethods = new();

        public static PyBoundMethod __object_method(string helper) =>
            ObjectMethods.GetOrAdd(helper, name => new PyBoundMethod(typeof(Builtins), name));

        public static object __object_new(Type cls)
        {
            if (!cls.IsClass || cls.IsAbstract || cls == typeof(string) || typeof(Delegate).IsAssignableFrom(cls))
                throw new InvalidCastException($"object.__new__({PyTypeName(cls)}) is not safe");
            return System.Runtime.CompilerServices.RuntimeHelpers.GetUninitializedObject(cls);
        }

        public static object? __object_init(object? value) => null;

        public static object? __object_getattribute(object? obj, string name) =>
            TryGetAttr(obj, name, out var value, allowFallback: false) ? value : throw new MissingMemberException(name);

        public static object? __object_setattr(object? obj, string name, object? value)
        {
            setattr(obj, name, value);
            return null;
        }

        public static object? __object_delattr(object? obj, string name)
        {
            delattr(obj, name);
            return null;
        }

        static Type? FindNestedType(Type? type, string name)
        {
            for (Type? current = type; current != null; current = current.BaseType)
                if (current.GetNestedType(name, BindingFlags.Public | BindingFlags.NonPublic) is Type nested)
                    return nested;
            return null;
        }

        public static object? __read_instance_attr(object instance, string name)
        {
            if (PyAttrDict.TryGetExtra(instance, name, out var value)) return value;
            if (FallbackAttributeMethod(instance, name) is MethodInfo getter)
                return Unwrapped(() => getter.Invoke(instance, [name]));
            throw new MissingMemberException($"'{PyTypeName(instance.GetType())}' object has no attribute '{name}'");
        }

        static bool TryFallbackAttribute(object instance, string name, out object? value)
        {
            value = null;
            if (FallbackAttributeMethod(instance, name) is not MethodInfo getter) return false;
            try { value = Unwrapped(() => getter.Invoke(instance, [name])); return true; }
            catch (MissingMemberException) { return false; }
        }

        static MethodInfo? FallbackAttributeMethod(object instance, string name) =>
            PyArgs.Best(instance.GetType().GetMethods(InstanceMembers).Where(method => method.Name == "__getattr__"),
                [name], null, out _);

        /// <summary>A generic extension method closed over the receiver's element type (count&lt;T&gt;(this List&lt;T&gt;, T) for a List&lt;long&gt;).</summary>
        static MethodInfo? CloseFor(MethodInfo m, Type receiver)
        {
            if (!m.IsGenericMethodDefinition) return m;
            var typeArgs = m.GetGenericArguments();
            var p0 = m.GetParameters()[0].ParameterType;
            if (typeArgs.Length != 1 || !p0.IsGenericType) return null;
            var def = p0.GetGenericTypeDefinition();
            var match = receiver.IsGenericType && receiver.GetGenericTypeDefinition() == def ? receiver
                : receiver.GetInterfaces().FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == def);
            int at = Array.IndexOf(p0.GetGenericArguments(), typeArgs[0]);
            if (match == null || at < 0) return null;
            try { return m.MakeGenericMethod(match.GetGenericArguments()[at]); } catch (ArgumentException) { return null; }
        }

        static object? InvokeExtension(string name, List<MethodInfo?> candidates, object self, object?[] args)
        {
            foreach (var m in candidates)
            {
                var ps = m!.GetParameters();
                int required = ps.Count(x => !x.IsOptional);
                if (args.Length + 1 < required || args.Length + 1 > ps.Length) continue;
                var call = new object?[ps.Length];
                call[0] = self;
                try
                {
                    for (int i = 1; i < ps.Length; i++) call[i] = i - 1 < args.Length ? ConvertTo(args[i - 1], ps[i].ParameterType) : ps[i].DefaultValue;
                }
                catch (Exception e) when (e is InvalidCastException || e is FormatException) { continue; }
                try { return m.Invoke(null, call); }
                catch (TargetInvocationException tie) when (tie.InnerException != null)
                {
                    System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(tie.InnerException).Throw();
                    throw;
                }
                catch (ArgumentException) { continue; }
            }
            throw new InvalidCastException($"{name}() does not take {args.Length} arguments here");
        }

        /// <summary>setattr(obj, name, value): a declared property or field (converted to its type), else an attribute kept beside the object.</summary>
        public static void setattr(object? o, string name, object? value)
        {
            if (o == null) throw new MissingMemberException($"'NoneType' object has no attribute '{name}'");
            if (o is Type t)
            {
                if (t.GetProperty(name, StaticMembers) is PropertyInfo sp && sp.CanWrite) { sp.SetValue(null, ConvertTo(value, sp.PropertyType)); return; }
                if (t.GetField(name, StaticMembers) is FieldInfo sf && !sf.IsInitOnly) { sf.SetValue(null, ConvertTo(value, sf.FieldType)); return; }
                throw new MissingMemberException($"type object '{PyTypeName(t)}' has no attribute '{name}' (Typhon classes cannot gain attributes at run time)");
            }
            if (o is PyFunction pf)
            {
                switch (name)
                {
                    case "__name__": pf.__name__ = (string)value!; return;
                    case "__qualname__": pf.__qualname__ = (string)value!; return;
                    case "__doc__": pf.__doc__ = value; return;
                    case "__wrapped__": pf.__wrapped__ = value; return;
                    case "__module__": pf.__module__ = (string)value!; return;
                }
                (pf._attrs ??= new Dictionary<string, object?>())[name] = value;
                return;
            }
            var type = o.GetType();
            if (type.GetProperty(name, InstanceMembers) is PropertyInfo p && p.CanWrite && p.GetIndexParameters().Length == 0) { p.SetValue(o, ConvertTo(value, p.PropertyType)); return; }
            if (type.GetField(name, InstanceMembers) is FieldInfo f && !f.IsInitOnly) { f.SetValue(o, ConvertTo(value, f.FieldType)); return; }
            new PyAttrDict(o)[name] = value;
        }

        public static void delattr(object? o, string name)
        {
            if (o != null && PyAttrDict.RemoveExtra(o, name)) return;
            if (o is PyFunction pf && pf._attrs != null && pf._attrs.Remove(name)) return;
            throw new MissingMemberException($"'{(o == null ? "NoneType" : PyTypeName(o.GetType()))}' object has no attribute '{name}' (or it is declared by its class)");
        }

        static object? ConvertTo(object? v, Type t) =>
            v == null || t.IsInstanceOfType(v) || t == typeof(object) ? v
            : System.Convert.ChangeType(v, Nullable.GetUnderlyingType(t) ?? t, System.Globalization.CultureInfo.InvariantCulture);
    }
